import json

alert_id = inputs.get('alert_id') or inputs.get('alertId')
create_incident = inputs.get('create_incident', inputs.get('createIncident', True))
if not alert_id:
    raise ValueError('alert_id is required')

result = tool.run_safe('security_alert_triage', alert_id=alert_id, create_incident=bool(create_incident))
if not result['success']:
    outputs['success'] = False
    outputs['error'] = result['error']
else:
    try:
        triage = json.loads(result['text']) if isinstance(result.get('text'), str) else result.get('obj')
    except Exception:
        triage = {'raw': result.get('text', '')}
    outputs['success'] = True
    outputs['triage_result'] = triage
    outputs['incident_id'] = triage.get('incident_id') if isinstance(triage, dict) else None
    outputs['summary'] = triage.get('summary') if isinstance(triage, dict) else result.get('text', '')
